function drawBuilding(b){const palette=[['#d2b798','#b69d81','#897b69'],['#b7b9aa','#92998f','#687974'],['#cf9e88','#b27d70','#79645d'],['#b9c9bd','#91aaa5','#718a8a']][b.tone];
